export default async function (ctx) {
  const out = [];
  const tries = [
    ['https://api.example.com/', { method: 'TRACE' }],
    ['https://api.example.com/', { headers: { Cookie: 'a=b' } }],
    ['https://api.example.com/', { headers: { 'User-Agent': 'me' } }],
    ['https://api.example.com/', { body: 'x' }],
    ['https://api.example.com/', { method: 'POST', body: 'x'.repeat(65537) }],
    ['https://api.example.com/', 'nope'],
  ];
  for (const [u, init] of tries) {
    try { await ctx.fetch(u, init); out.push('sent'); } catch (e) { out.push(e.code + ': ' + e.message); }
  }
  return out.join('\n');
}
